import { useState } from 'react';

function OrderForm() {
  const [itemCount, setItemCount] = useState(1);
  const [pricePerItem, setPricePerItem] = useState(9.99);

  const total = itemCount * pricePerItem; // derived value, recalculated every render

  return (
    <div>
      <label>
        Quantity:
        <input
          type="number"
          value={itemCount}
          onChange={(event) => setItemCount(Number(event.target.value))}
        />
      </label>

      <p>Price per item: ${pricePerItem.toFixed(2)}</p>
      <p>Total: ${total.toFixed(2)}</p>

      <button onClick={() => setItemCount(itemCount + 1)}>
        Add One More
      </button>
    </div>
  );
}

