sections.content:
import { useEffect } from 'react';

useEffect(() => {
  // this code runs after the component renders
}, [dependency1, dependency2]); // the dependency array

The dependency array's contents change useEffect's behavior dramatically:
- No dependency array at all: the effect runs after every single render, with no exceptions — rarely what you actually want, and easy to accidentally cause performance problems with
- An empty array []: the effect runs exactly once, right after the component's first render, and never again afterward — the standard pattern for one-time setup, like an initial data fetch
- An array with specific values [userId]: the effect runs after the first render, and then again any time userId specifically changes between renders, but not for other unrelated re-renders

An effect can also optionally return a 'cleanup function', which React runs right before the component is removed from the page, or right before the effect runs again due to a dependency changing — commonly used to cancel subscriptions, clear timers, or otherwise prevent leftover side effects from a previous render.

sections.code:
import { useState, useEffect } from 'react';

function UserProfile({ userId }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    setError(null);

    async function loadUser() {
      try {
        const response = await fetch(`/api/users/${userId}`);
        if (!response.ok) {
          throw new Error(`Request failed with status ${response.status}`);
        }
        const data = await response.json();
        setUser(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }

    loadUser();
  }, [userId]); // re-runs whenever userId changes, not on every unrelated render

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error: {error}</p>;
  return <h2>{user.name}</h2>;
}

