  const [searchTerm, setSearchTerm] = useState('');

  return (
    <div>
      <SearchInput searchTerm={searchTerm} onSearchChange={setSearchTerm} />
      <ResultsList products={products} searchTerm={searchTerm} />
    </div>
  );
}

