// STEP 1 - Components:
// - TaskFilterPage (top-level container)
//   - FilterButtons (the all/active/completed buttons)
//   - TaskList (renders the filtered list)
//     - TaskItem (one individual task, repeated)

// STEP 2 - Data involved:
// - the full array of task objects
// - the currently selected filter ('all' | 'active' | 'completed')
// - each task's own completed boolean
// - the FILTERED list actually shown (depends on both the full array and the filter)

// STEP 3 - Classify each:
// - full array of tasks -> state (it can change: add/delete/toggle)
// - currently selected filter -> state (changes when a filter button is clicked)
// - each task's completed boolean -> part of the task object itself, updated via state
// - the FILTERED list -> NOT its own state; calculated fresh via .filter() every render

// STEP 4 - Where state should live:
// - both 'tasks' array and 'selectedFilter' must live in TaskFilterPage,
//   since it's the lowest common ancestor of FilterButtons (changes the filter)
//   and TaskList (needs both the tasks AND the filter to compute its output)

// STEP 5 - Rendering patterns:
// - TaskList uses .map() with task.id as key (lesson 8)
// - Each TaskItem might use a ternary for a checked/unchecked icon (lesson 7)
// - An empty-filtered-list case could use && or an early return for a
//   'No tasks match this filter' message (lesson 7)

// Only NOW would implementation actually begin, informed by this plan
function TaskFilterPage() {
  const [tasks, setTasks] = useState([/* ... */]);
  const [selectedFilter, setSelectedFilter] = useState('all');

  const filteredTasks = tasks.filter((task) => {
    if (selectedFilter === 'active') return !task.completed;
    if (selectedFilter === 'completed') return task.completed;
    return true; // 'all'
  });

  return (
    <div>
      <FilterButtons selectedFilter={selectedFilter} onFilterChange={setSelectedFilter} />
      <TaskList tasks={filteredTasks} />
    </div>
  );
}

