codingChallenge.solutionExample:
// STEP 1 - Components: CartPage (container) -> CartBadge (shows item count),
//          CartItemList (renders items), CartItem (one item, repeated)
// STEP 2 - Data: array of cart items, each with quantity and price; the total price;
//          the total item count
// STEP 3 - Classify: cart items array -> state (can change: add/remove/update quantity).
//          total price and total item count -> derived, calculated from the cart items array
// STEP 4 - Placement: cart items array lives in CartPage, the lowest common ancestor
//          of CartBadge (needs item count) and CartItemList (needs the items themselves)
// STEP 5 - Rendering patterns: CartItemList uses .map() with item.id as key;
//          an empty cart uses an early return for a 'Your cart is empty' message

import { useState } from 'react';

function CartBadge({ itemCount }) {
  return <span className="badge">{itemCount} items</span>;
}

function CartItem({ name, price, quantity }) {
  return <li>{name} - ${price} x {quantity}</li>;
}

function CartItemList({ items }) {
  if (items.length === 0) return <p>Your cart is empty.</p>;
  return (
    <ul>
      {items.map((item) => (
        <CartItem key={item.id} name={item.name} price={item.price} quantity={item.quantity} />
      ))}
    </ul>
  );
}

function CartPage() {
  const [items, setItems] = useState([
    { id: 1, name: 'Notebook', price: 5, quantity: 2 },
    { id: 2, name: 'Pen', price: 2, quantity: 3 }
  ]);

  const itemCount = items.reduce((sum, item) => sum + item.quantity, 0);
  const totalPrice = items.reduce((sum, item) => sum + item.price * item.quantity, 0);

  return (
    <div>
      <CartBadge itemCount={itemCount} />
      <CartItemList items={items} />
      <p>Total: ${totalPrice}</p>
    </div>
  );
}
